// 1. Использование const и объекта
const student = {
    lastName: "Сирош",
    firstName: "Александр",
    group: "AI241"
};

// 2. Использование массива с баллами
const scores = [85, 92, 78, 95, 64, 88];

// 3. Использование let
let total = 0;
let honorsCount = 0;

// 4. Цикл for для обхода массива
for (let i = 0; i < scores.length; i++) {
    total += scores[i];

    // 5. Конструкция if / else
    if (scores[i] >= 90) {
        honorsCount++;
    } else {
        // обычный балл
    }
}

const average = total / scores.length;

// 6. Возвращаем объект в msg.payload
msg.topic = "lab2/sirosh/function";
msg.payload = {
    student: student,
    allScores: scores,
    averageScore: Number(average.toFixed(2)),
    honorsCount: honorsCount,
    status: average >= 75 ? "Passed" : "Needs Review"
};

return msg;
